#!/usr/bin/env bash
# Variables below are used by the scripts that source this file.
# shellcheck disable=SC2034
# Shared helpers for midpoint/run-campaign.sh and test/e2e-midpoint.sh.
# Sourced after ../lib.sh (which cd's to lab/pam, sets -euo pipefail and
# umask 077). Never executed directly.
#
# Credentials: the midPoint administrator password is read from .env
# (MIDPOINT_ADMIN_PASSWORD, generated by pam-up.sh) into a NON-exported shell
# variable and handed to curl as a config file on stdin, so it never appears
# in any process's argument list, in the environment of child processes, or
# in output.

MP_URL="${MIDPOINT_URL:-http://127.0.0.1:8082/midpoint}"
MP_REST="$MP_URL/ws/rest"
MP_DIR="$PAM_DIR/midpoint"

# Fixed OIDs (lab namespace c0471e00-0000-4000-8000-*, see objects/).
MP_DEF_OID="c0471e00-0000-4000-8000-000000000401"
MP_TASK_CREATE="c0471e00-0000-4000-8000-000000000501"
MP_TASK_CLOSE_STAGE="c0471e00-0000-4000-8000-000000000502"
MP_TASK_REMEDIATION="c0471e00-0000-4000-8000-000000000503"

mp_load_password() {
  [[ -f .env ]] || die ".env missing - run ./pam-up.sh first"
  MP_PW="$(sed -n 's/^MIDPOINT_ADMIN_PASSWORD=//p' .env | tail -n 1)"
  [[ -n "$MP_PW" ]] || die "MIDPOINT_ADMIN_PASSWORD is empty in .env - run ./pam-up.sh first"
}

# mp_curl PATH [curl args...] -> response body on stdout.
# MP_USER / MP_PW override the identity (e2e uses a wrong password once).
mp_curl() {
  local pw="${MP_PW//\\/\\\\}"; pw="${pw//\"/\\\"}"
  printf 'user = "%s:%s"\n' "${MP_USER:-administrator}" "$pw" \
    | curl -sS -K - -H 'Accept: application/json' "$MP_REST/$1" "${@:2}"
}

# mp_code PATH [curl args...] -> HTTP status only (body discarded).
mp_code() { mp_curl "$1" -o /dev/null -w '%{http_code}' "${@:2}" 2>/dev/null || true; }

mp_wait_up() { # wait for midPoint to answer REST as administrator (first start: minutes)
  local code=""
  for _ in $(seq 1 100); do
    code="$(mp_code self)"
    [[ "$code" == 200 ]] && return 0
    [[ "$code" == 401 ]] && die "midPoint refused the administrator password from .env (401)"
    sleep 3
  done
  die "midPoint REST did not answer 200 at $MP_REST/self (last: ${code:-none}) - is the stack up (./pam-up.sh)?"
}

# REST collection for an object file's root element.
mp_collection() {
  case "$1" in
    org) echo orgs ;;
    role) echo roles ;;
    user) echo users ;;
    task) echo tasks ;;
    accessCertificationDefinition) echo accessCertificationDefinitions ;;
    accessCertificationCampaign) echo accessCertificationCampaigns ;;
    *) die "no REST collection mapped for <$1>" ;;
  esac
}

mp_root_element() { # first element after the XML declaration and comments
  perl -0777 -ne 's/<!--.*?-->//gs; s/<\?.*?\?>//gs; print "$1\n" if /<([A-Za-z][A-Za-z0-9]*)[\s>]/' "$1"
}
mp_file_oid() { # oid attribute of the root element
  perl -0777 -ne 's/<!--.*?-->//gs; print "$1\n" if /<[A-Za-z][A-Za-z0-9]*\b[^>]*?\boid="([0-9a-f-]+)"/s' "$1"
}

# mp_put FILE [BODY_FILE]: PUT (create or replace) the object with its fixed
# OID. BODY_FILE lets a caller send an edited copy (task templates).
mp_put() {
  local file="$1" body="${2:-$1}" el oid coll out code
  el="$(mp_root_element "$file")"; oid="$(mp_file_oid "$file")"
  [[ "$oid" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]] || die "$file: no fixed oid"
  coll="$(mp_collection "$el")"
  out="$(mktemp)"
  code="$(mp_curl "$coll/$oid" -X PUT -H 'Content-Type: application/xml' --data-binary @"$body" \
           -o "$out" -w '%{http_code}' || true)"
  if [[ ! "$code" =~ ^20[0-4]$ ]]; then
    echo "--- midPoint said (HTTP $code):" >&2
    jq -r '.. | .message? // empty' "$out" 2>/dev/null | head -n 5 >&2 || head -c 2000 "$out" >&2
    rm -f "$out"
    die "PUT $coll/$oid ($(basename "$file")) failed"
  fi
  rm -f "$out"
  printf '%s' "$code"
}

mp_get() { mp_curl "$1" -f "${@:2}"; } # GET PATH -> JSON (fails on HTTP >= 400)

# mp_run_task TEMPLATE [CAMPAIGN_OID]: PUT the task (fixed OID, replacing the
# previous run's task), wait until midPoint closes it, require success.
mp_run_task() {
  local tpl="$1" campaign="${2:-}" oid body state status msg
  oid="$(mp_file_oid "$tpl")"
  body="$(mktemp)"
  if [[ -n "$campaign" ]]; then
    [[ "$campaign" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]] || die "bad campaign oid"
    sed "s|__CAMPAIGN_OID__|$campaign|" "$tpl" > "$body"
  else
    cp "$tpl" "$body"
  fi
  mp_put "$tpl" "$body" >/dev/null
  rm -f "$body"
  for _ in $(seq 1 120); do
    state="$(mp_get "tasks/$oid" | jq -r '.task.executionState // empty')"
    [[ "$state" == closed ]] && break
    sleep 2
  done
  [[ "$state" == closed ]] || die "task $(basename "$tpl") not closed after 240 s (state: ${state:-none})"
  status="$(mp_get "tasks/$oid" | jq -r '.task.resultStatus // empty')"
  if [[ "$status" != success ]]; then
    msg="$(mp_get "tasks/$oid" | jq -r '[.. | .message? // empty] | unique | .[0:3] | join(" | ")')"
    die "task $(basename "$tpl") finished with result '$status': $msg"
  fi
}

mp_campaign_state() { mp_get "accessCertificationCampaigns/$1" | jq -r '.accessCertificationCampaign.state'; }

# OIDs of every campaign created from the definition, one per line.
mp_campaign_oids() {
  mp_get accessCertificationCampaigns \
    | jq -r --arg d "$MP_DEF_OID" '[.. | objects | select(.definitionRef?.oid? == $d) | .oid] | unique | .[]'
}

sha256_file() { # portable: macOS shasum / Linux sha256sum
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$@"; else shasum -a 256 "$@"; fi
}
